export const tFor = (lang: string, vibe: string, key: keyof typeof T.id.casual, vars?: Record<string, string>) => {
  const l = (T as any)[lang] ? lang : "en";
  const v = vibe === "pro" ? "pro" : "casual";
  let str = ((T as any)[l][v][key] as string) || ((T as any).en.casual[key] as string) || key;
  if (vars) for (const k in vars) str = str.replace(`{${k}}`, vars[k]);
  return str;
};